"""Minimal YAML renderer — standard library only."""

from plugins import PluginError, Renderer, register


def _yaml_scalar(value) -> str:
    """Return a YAML-safe scalar string for *value*."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return repr(value)
    if isinstance(value, str):
        # Quote if the string could be misinterpreted or is empty.
        if (
            not value
            or value in ("true", "false", "null", "yes", "no", "on", "off")
            or value[0] in ("{", "}", "[", "]", ",", "&", "*", "?", "|", "-", "<", ">", "=", "!", "%", "@", "`")
            or "\n" in value
            or value != value.strip()
        ):
            # Use single quotes; escape internal single quotes by doubling.
            escaped = value.replace("'", "''")
            return f"'{escaped}'"
        return value
    if isinstance(value, list):
        items = ", ".join(_yaml_scalar(v) for v in value)
        return f"[{items}]"
    return str(value)


def _render_yaml(rows: list[dict]) -> str:
    """Render a list of flat dicts as a YAML sequence of mappings."""
    if not rows:
        return ""
    keys = list(rows[0].keys())
    lines: list[str] = []
    for row in rows:
        lines.append("-")
        for key in keys:
            val = row.get(key)
            lines.append(f"  {key}: {_yaml_scalar(val)}")
    return "\n".join(lines) + "\n"


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        return _render_yaml(rows)

